// index.jsx (React + React Router v6)
import { BrowserRouter, Routes, Route, Link } from "react-router-dom";

function Home() {
  return <h2>Inicio</h2>;
}
function User({ id }) {
  return <h2>Usuario {id}</h2>;
}
function App() {
  return (
    <BrowserRouter>
      <nav>
        <Link to="/">Inicio</Link>{" | "}
        <Link to="/user/42">Usuario 42</Link>
      </nav>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route
          path="/user/:id"
          element={<UserWrapper />}
        />
      </Routes>
    </BrowserRouter>
  );
}
function UserWrapper() {
  const { id } = useParams();
  return <User id={id} />;
}
export default App;
